contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address recipient) public {
        require(recipient != address(0));

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;
        uint256 rBalBefore = recipient.balance;

        c.withdrawAll(recipient); if (__ESBMC_reverted()) return;

        uint256 cBalAfter = address(c).balance;
        uint256 rBalAfter = recipient.balance;
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        assert(ownerAfter == ownerBefore && cBalAfter == 0 && rBalAfter == rBalBefore + cBalBefore);
    }
}

